import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Table } from 'antd'

export default function NursingCarePlanDetails({ selectedAdmission, updated, setupdated }) {

    const [admissionNursingcarePlans, setadmissionNursingcarePlans] = useState([])

    const getAdmissionNursingCarePlansApi=useApi(hospitalsApi.hospitalInpatientAction)
    const getAdmissionNursingCarePlans = async () => {
        await getAdmissionNursingCarePlansApi.request({
            "action":"GetAdmissionNursingCarePlans",
            "admission":selectedAdmission.id
        
        })
     }

    useEffect(() => {
        if (getAdmissionNursingCarePlansApi.data) {
           if(getAdmissionNursingCarePlansApi.data.length){
                setadmissionNursingcarePlans(getAdmissionNursingCarePlansApi.data)
           }
        }
    }, [getAdmissionNursingCarePlansApi.data])


    useEffect(() => {
        if (selectedAdmission) {
            getAdmissionNursingCarePlans()
        }
    }, [selectedAdmission])

    useEffect(() => {
        if (selectedAdmission && updated) {
            getAdmissionNursingCarePlans()
        }
    }, [updated])


    const columns = [
        {
          title: 'Assessment',
          dataIndex: 'assessment',
          key: 'assessment',
        },
        {
          title: 'Nursing Diagnosis',
          dataIndex: 'nursing_diagnosis',
          key: 'nursing_diagnosis',
        },
        {
          title: 'Goals/Expected Outcome',
          dataIndex: 'goals_and_expected_outcome',
          key: 'goals_and_expected_outcome',
        },
        {
          title: 'Nursing Intervention',
          dataIndex: 'nursing_intervention',
          key: 'nursing_intervention',
        },
        {
          title: 'Rationale',
          dataIndex: 'rationale',
          key: 'rationale',
        },
        {
          title: 'Evaluation',
          dataIndex: 'evaluation',
          key: 'evaluation',
        },
      ];
    return (
        <div>
        
        <Table dataSource={admissionNursingcarePlans} columns={columns} />;
        </div>
    )
}
